import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_conversion_rate_none_counts_as_not_converted():
    events = [{"converted": True}, {"converted": None}, {"converted": False}]
    assert conversion_rate(events) == pytest.approx(1 / 3)
    assert conversion_rate([{"converted": None}]) == 0.0


def test_conversion_rate_empty():
    rate = conversion_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_conversion_rate_equal_groups():
    groups = {"a": [{"converted": True}, {"converted": False}], "b": [{"converted": True}, {"converted": False}]}
    assert pooled_conversion_rate(groups) == 0.5


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "small": [{"converted": True}],
        "large": [{"converted": True}, {"converted": False}, {"converted": None}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_conversion_rate_no_sessions(groups):
    rate = pooled_conversion_rate(groups)
    assert rate == 0.0
    assert isinstance(rate, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4, 8], 2, 12), ([1, 2, 4], 1, 4), ([1, 2, 4], 0, 0),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 3, 0), ([], 0, 0)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


def test_parse_session_log_one_line():
    assert parse_session_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "converted": True}]


def test_parse_session_log_flags_and_whitespace():
    assert parse_session_log([" x1 , 3 , 1 \n", "x2, -2 , 0", " x3 , 4 , \t"]) == [
        {"id": "x1", "day": 3, "converted": True},
        {"id": "x2", "day": -2, "converted": False},
        {"id": "x3", "day": 4, "converted": None},
    ]


def test_parse_session_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "#comment", "  # not,a,session,at,all", "x1,3,0", ""]
    assert parse_session_log(iter(lines)) == [{"id": "x1", "day": 3, "converted": False}]
    assert parse_session_log([]) == []


@pytest.mark.parametrize("bad_line", ["x", "x,1", "x,1,0,extra", "x,no,1", "x,1.5,1", "x,,0"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    lines = ["", "  # comment", "x,1,1", " \t", bad_line]
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_session_log(lines)


def test_dedupe_sessions_keeps_last_duplicate_id_and_sorts():
    events = [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 3, "converted": False},
        {"id": "a", "day": 9, "converted": True},
        {"id": "c", "day": 1, "converted": True},
        {"id": "a", "day": 3, "converted": None},
    ]
    assert dedupe_sessions(events) == [events[3], events[4], events[1]]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_inclusive_range_with_gaps():
    events = [
        {"day": 0, "converted": True},
        {"day": 2, "converted": True},
        {"day": 2, "converted": True},
        {"day": 3, "converted": False},
        {"day": 3, "converted": None},
        {"day": 5, "converted": True},
        {"day": 6, "converted": True},
    ]
    assert daily_conversion_counts(events, 1, 5) == [0, 2, 0, 0, 1]
    assert daily_conversion_counts(events, 2, 2) == [2]
    assert daily_conversion_counts(events, 5, 1) == []
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]


def test_campaign_summary_basic():
    e = [{"id": "a", "day": 1, "converted": True}, {"id": "b", "day": 2, "converted": False}]
    assert campaign_summary({"g": e}, 1) == {"rate": 0.5, "recent": 0, "groups": 1}


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 0), (3, 1), (10, 2)])
def test_campaign_summary_weighting_rounding_and_calendar_window(days, recent):
    groups = {
        "a": [{"day": 1, "converted": True}],
        "b": [{"day": 3, "converted": True}, {"day": 5, "converted": None}],
        "empty": [],
    }
    assert campaign_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_no_sessions(groups):
    assert campaign_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


@pytest.mark.parametrize("n, expected", [(0, []), (2, ["best", "a"]), (10, ["best", "a", "z", "zero"])])
def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name(n, expected):
    groups = {
        "z": [{"converted": True}, {"converted": False}],
        "empty": [],
        "zero": [{"converted": None}],
        "a": [{"converted": True}, {"converted": None}],
        "best": [{"converted": True}],
    }
    assert top_converting_groups(groups, n) == expected
    assert top_converting_groups({}, n) == []
    assert top_converting_groups({"empty": []}, n) == []


def test_conversion_rate_by_group_includes_empty_and_sorts_keys():
    groups = {"z": [], "b": [{"converted": True}, {"converted": None}], "a": [{"converted": False}]}
    rates = conversion_rate_by_group(groups)
    assert rates == {"a": 0.0, "b": 0.5, "z": None}
    assert list(rates) == ["a", "b", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, -1, 0], 0), ([1, 2, 3], 3), ([1, 0, 1, 1, 0, 1], 2),
     ([1, -1, 2], 1), ([0, 1, 1, 1], 3)],
)
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected

